mapper.select:
SELECT * FROM (
  SELECT a.*, ROWNUM rnum
    FROM (
       SELECT /*+ INDEX(T1 TB_CR_AH_SALES_TIP_RACT_PK) */ /* mkpca8888S0_S0 */

         FROM TB_CR_AH_SALES_TIP_RACT T1
        WHERE 1 = 1

          AND T1.SALZ_TIP_KDC = #{salzTipKdc}

       ORDER BY T1.BAS_DT DESC, T1.TRT_BRC, T1.TRTMN_ENO
    ) a
   WHERE ROWNUM <= #{offset} + #{pageSize}
)
WHERE rnum > #{offset}

SELECT /*+ INDEX(T1 TB_CR_AH_SALES_TIP_RACT_PK) */ /* mkpca8888S0_S1 */

  FROM TB_CR_AH_SALES_TIP_RACT T1
 WHERE T1.TRT_BRC      = #{trtBrc}
   AND T1.TRTMN_ENO    = #{trtmnEno}
   AND T1.SALZ_TIP_KDC = #{salzTipKdc}
   AND T1.BAS_DT       = #{basDt}

mapper.update:
UPDATE TB_CR_AH_SALES_TIP_RACT
   SET PRTO_CN = #{prtoCn}
     , INQ_CN  = #{inqCn}
     , INP_CN  = #{inpCn}
 WHERE TRT_BRC      = #{trtBrc}
   AND TRTMN_ENO    = #{trtmnEno}
   AND SALZ_TIP_KDC = #{salzTipKdc}
   AND BAS_DT       = #{basDt}

mapper.delete:
DELETE FROM TB_CR_AH_SALES_TIP_RACT
 WHERE TRT_BRC      = #{trtBrc}
   AND TRTMN_ENO    = #{trtmnEno}
   AND SALZ_TIP_KDC = #{salzTipKdc}
   AND BAS_DT       = #{basDt}
